function loadState(){try{const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}");return {...structuredClone(defaultState),...raw,profile:{...defaultState.profile,...(raw.profile||{})},customRecipes:Array.isArray(raw.customRecipes)?raw.customRecipes:[]}}catch{return structuredClone(defaultState)}}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}function allRecipes(){return [...CCD_RECIPES,...state.customRecipes]}function recipeById(id){return allRecipes().find(r=>r.id===id)}
function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove("show"),2200)}function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function baseCalories(r){return Math.round(r.nutrition?.calories ?? r.calories ?? estimateCalories(r))}
function estimateCalories(r){const text=(r.name+" "+r.group).toLowerCase();let c=260;if(/drink|coffee|tea|latte/.test(text))c=95;if(/dip|sauce|frosting/.test(text))c=150;if(/cookie|donut|brownie|cake|muffin/.test(text))c=230;if(/sandwich|philly|pizza|burrito|quesadilla|pasta/.test(text))c=430;if(/egg|breakfast/.test(text))c=280;if(/snack|side/.test(text))c=200;return c}
function autoNutrition(r){if(r.nutrition){return {calories:Math.round(r.nutrition.calories??baseCalories(r)),protein:Math.round(r.nutrition.protein??0),carbs:Math.round(r.nutrition.carbs??0),fat:Math.round(r.nutrition.fat??0),fiber:Math.round(r.nutrition.fiber??0),exact:true}}const c=baseCalories(r),t=(r.name+" "+r.group+" "+(r.ingredients||[]).join(" ")).toLowerCase();let p=.18,carb=.50,f=.32,fiber=Math.max(2,Math.round(c/115));if(/chicken|steak|egg|yogurt|cottage|turkey/.test(t)){p=.28;carb=.39;f=.33}if(/coffee|tea|drink|latte/.test(t)){p=.16;carb=.60;f=.24;fiber=Math.max(1,Math.round(c/120))}if(/brownie|cake|cookie|donut|chocolate/.test(t)){p=.11;carb=.56;f=.33}if(/wrap|burrito|pizza|pasta|sandwich|philly/.test(t)){p=.24;carb=.44;f=.32}return {calories:c,protein:Math.round(c*p/4),carbs:Math.round(c*carb/4),fat:Math.round(c*f/9),fiber,exact:false}}
function recipeImage(r){const t=(r.name+" "+r.group).toLowerCase();if(/coffee|tea|drink|latte|mocha/.test(t))return imageMap.coffee;if(/donut/.test(t))return imageMap.donut;if(/chocolate|brownie|cake|cookie/.test(t))return imageMap.chocolate;if(/sandwich|philly|bagel|toast/.test(t))return imageMap.sandwich;if(/bowl|salad/.test(t))return imageMap.bowl;if(/savory|pizza|pasta|wrap|burrito|egg|chicken/.test(t))return imageMap.savory;return imageMap.sweet}
function tasteText(r){if(r.taste)return r.taste;const t=r.name.toLowerCase();if(/chocolate|brownie|lava/.test(t))return"RICH, CHOCOLATEY AND COZY — EXPECT A SOFT CENTER AND DESSERT-ENERGY WITHOUT LOSING THE CCD STRUCTURE.";if(/cinnamon|pancake|french toast/.test(t))return"WARM, CINNAMONNY AND BREAKFAST-COZY — SOFT, SWEET-LEANING AND MADE FOR A SLOW MORNING VIBE.";if(/philly|steak|sandwich|bagel/.test(t))return"SAVORY, TOASTY AND SATISFYING — EXPECT A JUICY CENTER, CRISP EDGES AND MELTY COMFORT-FOOD ENERGY.";if(/coffee|tea|latte/.test(t))return"SMOOTH, AROMATIC AND SIP-ABLE — EXPECT A COZY CAFÉ VIBE WITH A LIGHT SWEET FINISH.";if(/egg|savory|chicken|pizza|pasta|wrap/.test(t))return"SAVORY, WARM AND COMFORTING — BUILT TO FEEL LIKE A REAL MEAL, NOT A SAD SUBSTITUTE.";return"SOFT, COZY AND PLAYFUL — EXPECT A BERRY-VIBES COMFORT FOOD MOMENT WITH AN EASY CCD TWIST."}
function recipeFacts(r){const n=autoNutrition(r),t=(r.name+" "+r.group).toLowerCase();const texture=/chocolate|brownie|cake|lava/.test(t)?"🍫 EXPECT A SOFT, RICH, DESSERT-STYLE BITE.":/sandwich|philly|bagel|toast/.test(t)?"🥯 EXPECT TOASTY EDGES + A SAVORY, SATISFYING CENTER.":/coffee|tea|drink|latte/.test(t)?"☕️ EXPECT A COZY SIP WITH CAFÉ ENERGY.":"🍓 EXPECT A COZY, REPEATABLE CCD VIBE.";return [`🔥 ABOUT ${n.calories} KCAL PER SAVED SERVING IN THIS ARCHIVE CARD.`,`💪🏽 ${n.protein}G PROTEIN + 🌾 ${n.fiber}G FIBER IN THE CURRENT SAVED NUTRITION.`,texture]}
function movementFactLines(){const key=$("#activitySelect")?.value||"walk",map={walk:["🚶🏽‍♀️ GENTLE WALK = EASY, STEADY MOVEMENT.","⏱️ YOUR TIME SLIDER SETS THE BURN ESTIMATE AUTOMATICALLY.","✨ WALK BURN STAYS SEPARATE FROM YOUR FOOD MAINTENANCE REFERENCE."],yoga:["🧘🏽‍♀️ YOGA = MOBILITY + CONTROL + BREATHING.","⏱️ SLIDE THE MINUTES; NO TYPING NEEDED.","✨ THE SITE USES A CONSISTENT MET-STYLE ESTIMATE FOR THE LOG."],barre:["🩰 BARRE MIXES SMALL CONTROLLED MOVES WITH BALANCE.","⏱️ YOUR SELECTED MINUTES DRIVE THE AUTO BURN ESTIMATE.","✨ LOGGING EARNS BERRY XP WITHOUT CHANGING YOUR FOOD TOTAL."],dance:["🕺🏽 JUST DANCE / MJ EXPERIENCE = THE ARCADE CARDIO OPTION.","🎵 MORE MINUTES = A HIGHER AUTO BURN ESTIMATE.","✨ MOVEMENT BURN IS DISPLAYED SEPARATELY FROM FOOD CALORIES."],pilates:["✨ PILATES = CONTROLLED CORE-FOCUSED MOVEMENT.","⏱️ USE THE SLIDER FOR DURATION — NO MANUAL NUMBER ENTRY.","💜 THE LOG SAVES YOUR EXACT CLICK TIME AUTOMATICALLY."]};return map[key]}
function getGreeting(){const h=new Date().getHours();if(h<12)return"GOOD MORNING ☀️";if(h<17)return"GOOD AFTERNOON ✨";if(h<21)return"GOOD EVENING 🌙";return"LATE-NIGHT BERRY MODE 🌌"}
function applyTheme(){const themes=["blueberry","peach","mint","midnight","purple","sunshine","orange","red","gray","cloud","magenta"];document.body.classList.remove(...themes.map(x=>"theme-"+x));if(state.profile.theme!=="berry"&&themes.includes(state.profile.theme))document.body.classList.add("theme-"+state.profile.theme);document.documentElement.style.setProperty("--accent",state.profile.accent||"#7f3cff");document.querySelector('meta[name="theme-color"]').setAttribute("content",state.profile.accent||"#7f3cff")}
function safeImg(img,fallbackEmoji="🍓"){if(!img)return;img.addEventListener("error",()=>{const wrap=img.parentElement;img.remove();if(wrap){wrap.style.display="grid";wrap.style.placeItems="center";wrap.style.fontSize="64px";wrap.textContent=fallbackEmoji}},{once:true})}
function buildSotd(){const sel=$("#sotdSelect");if(!sel)return;sel.innerHTML=SOTD_ITEMS.map((x,i)=>`<option value="${i}">${escapeHtml(x.name)}</option>`).join("");state.sotdIndex=clamp(Number(state.sotdIndex)||0,0,SOTD_ITEMS.length-1);sel.value=state.sotdIndex;updateSotdPreview()}
function updateSotdPreview(){const sel=$("#sotdSelect");if(!sel)return;const i=clamp(+sel.value||0,0,SOTD_ITEMS.length-1),item=SOTD_ITEMS[i],q=$("#sotdQty");state.sotdIndex=i;q.min=item.min;q.max=item.max;q.step=item.step;if(+q.value<item.min||+q.value>item.max)q.value=item.min;const qty=+q.value,n=sotdMacros(item),total={calories:Math.round(n.calories*qty),carbs:Math.round(n.carbs*qty),protein:Math.round(n.protein*qty),fat:Math.round(n.fat*qty),fiber:Math.round(n.fiber*qty)};$("#sotdQtyOut").textContent=`${qty} ${item.unit}${qty===1?"":"S"}`;$("#sotdPreview").innerHTML=[["CAL",total.calories],["CARBS",total.carbs+"G"],["PROTEIN",total.protein+"G"],["FIBER",total.fiber+"G"]].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join("");$("#sotdNote").textContent=item.note;$("#sotdPickName").textContent=item.name;$("#sotdPickMeta").textContent=`${item.min}${item.max!==item.min?"–"+item.max:""} ${item.unit}${item.max===1?"":"S"} · ${item.recorded?"RECORDED CALORIE":"AUTO ESTIMATE"}`;$("#sotdEmoji").textContent=item.emoji;const img=$("#sotdImage");img.src=item.image;img.alt=`Snack photography representing ${item.name}`;saveState()}
function randomizeSotd(){let i=state.sotdIndex||0;if(SOTD_ITEMS.length>1){let next=i;while(next===i)next=Math.floor(Math.random()*SOTD_ITEMS.length);i=next}state.sotdIndex=i;$("#sotdSelect").value=i;$("#sotdQty").value=SOTD_ITEMS[i].min;updateSotdPreview();confetti(16);toast("NEW SOTD PICK 🎲🍪")}
function logSotd(){const item=SOTD_ITEMS[clamp(+$("#sotdSelect").value||0,0,SOTD_ITEMS.length-1)],qty=+$("#sotdQty").value,n=sotdMacros(item),scaled={calories:Math.round(n.calories*qty),protein:Math.round(n.protein*qty),carbs:Math.round(n.carbs*qty),fat:Math.round(n.fat*qty),fiber:Math.round(n.fiber*qty)};state.logs.push({type:"food",emoji:item.emoji,name:`SOTD · ${item.name}`,detail:`${qty} ${item.unit}${qty===1?"":"S"} · ${item.recorded?"RECORDED CALORIE / AUTO MACROS":"AUTO CCD ESTIMATE"}`,nutrition:scaled,at:Date.now()});state.xp+=25;confetti(18);toast("SOTD LOGGED +25 XP 🍪");updateDashboard()}

function buildRestaurants(){const chainSel=$("#restaurantChain"),itemSel=$("#restaurantItem");if(!chainSel||!itemSel)return;chainSel.innerHTML=RESTAURANT_CHAINS.map((x,i)=>`<option value="${i}">${escapeHtml(x.name)}</option>`).join("");state.restaurantIndex=clamp(Number(state.restaurantIndex)||0,0,RESTAURANT_CHAINS.length-1);chainSel.value=state.restaurantIndex;populateRestaurantItems()}
function populateRestaurantItems(){const idx=clamp(+$("#restaurantChain").value||0,0,RESTAURANT_CHAINS.length-1),chain=RESTAURANT_CHAINS[idx];state.restaurantIndex=idx;$("#restaurantItem").innerHTML=chain.items.map((x,i)=>`<option value="${i}">${escapeHtml(x.name)}</option>`).join("");$("#restaurantPortion").value=1;saveState();updateRestaurantPreview()}
function updateRestaurantPreview(){const c=RESTAURANT_CHAINS[clamp(+$("#restaurantChain").value||0,0,RESTAURANT_CHAINS.length-1)],item=c.items[clamp(+$("#restaurantItem").value||0,0,c.items.length-1)],m=+$("#restaurantPortion").value;$("#restaurantPortionOut").textContent=m.toFixed(2).replace(/0+$/,'').replace(/\.$/,'')+"×";const n={calories:Math.round(item.calories*m),carbs:Math.round(item.carbs*m),protein:Math.round(item.protein*m),fat:Math.round(item.fat*m),fiber:Math.round(item.fiber*m)};$("#restaurantPreview").innerHTML=[["CAL",n.calories],["CARBS",n.carbs+"G"],["PROTEIN",n.protein+"G"],["FAT",n.fat+"G"],["FIBER",n.fiber+"G"]].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join("");$("#restaurantSource").textContent=(item.verified?"✅ VERIFIED · ":"⚠️ ESTIMATE · ")+c.source+" · STANDARD ITEM; CUSTOMIZATIONS MAY CHANGE VALUES.";$("#restaurantPhotoBadge").textContent=c.name+" 🍟";const img=$("#restaurantImage");img.src=c.image;img.alt=`Restaurant food photography representing ${c.name}`}
function logRestaurant(){const c=RESTAURANT_CHAINS[clamp(+$("#restaurantChain").value||0,0,RESTAURANT_CHAINS.length-1)],item=c.items[clamp(+$("#restaurantItem").value||0,0,c.items.length-1)],m=+$("#restaurantPortion").value,n={calories:Math.round(item.calories*m),protein:Math.round(item.protein*m),carbs:Math.round(item.carbs*m),fat:Math.round(item.fat*m),fiber:Math.round(item.fiber*m)};state.logs.push({type:"food",emoji:"🍟",name:`${c.name} · ${item.name}`,detail:`${m}× PORTION · ${item.verified?"VERIFIED RESTAURANT NUTRITION":"ESTIMATE"}`,nutrition:n,at:Date.now()});state.xp+=25;saveState();confetti(18);toast("RESTAURANT FOOD LOGGED +25 XP 🍟");updateDashboard()}
function convertiblePantry(){return PANTRY.filter(x=>["TSP","TBSP","1/4 CUP"].includes(x.unit))}
function unitBaseFactor(item,unit){if(item.unit==="TBSP")return unit==="tsp"?1/3:unit==="tbsp"?1:16;if(item.unit==="TSP")return unit==="tsp"?1:unit==="tbsp"?3:48;if(item.unit==="1/4 CUP")return unit==="tsp"?1/12:unit==="tbsp"?1/4:4;return 0}
function buildUnitLab(){const sel=$("#unitIngredient");if(!sel)return;sel.innerHTML=convertiblePantry().map(x=>`<option value="${x.id}">${x.name}</option>`).join("");updateUnitLab()}
function updateUnitLab(){const item=pantryItem($("#unitIngredient")?.value),unit=$("#unitSelect")?.value,amt=+$("#unitAmount")?.value;if(!item||!unit)return;const factor=unitBaseFactor(item,unit)*amt,unitLabel=unit.toUpperCase(),n={calories:item.calories*factor,carbs:item.carbs*factor,protein:item.protein*factor,fat:item.fat*factor,fiber:item.fiber*factor};$("#unitAmountOut").textContent=`${amt} ${unitLabel}`;$("#unitNutrition").innerHTML=[["CALORIES",Math.round(n.calories)],["CARBS",n.carbs.toFixed(1)+"G"],["PROTEIN",n.protein.toFixed(1)+"G"],["FAT",n.fat.toFixed(1)+"G"],["FIBER",n.fiber.toFixed(1)+"G"]].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join("");const tsp=Math.round(item.calories*unitBaseFactor(item,"tsp")*10)/10,tbsp=Math.round(item.calories*unitBaseFactor(item,"tbsp")*10)/10,cup=Math.round(item.calories*unitBaseFactor(item,"cup"));$("#unitReference").innerHTML=`<span>🥄 1 TSP ≈ <b>${tsp} KCAL</b></span><span>🥄 1 TBSP ≈ <b>${tbsp} KCAL</b></span><span>🥣 1 CUP ≈ <b>${cup} KCAL</b></span>`}
function buildSelects(){const recipes=allRecipes(),options=recipes.map(r=>`<option value="${escapeHtml(r.id)}">${escapeHtml(r.name)}</option>`).join("");["#foodSelect","#battleA","#battleB"].forEach(s=>$(s).innerHTML=options);if(recipes[10])$("#battleB").value=recipes[10].id;const groups=[...new Set(recipes.map(r=>r.group))].sort();$("#groupFilter").innerHTML='<option value="all">ALL CCD WORLDS</option>'+groups.map(g=>`<option>${escapeHtml(g)}</option>`).join("");$("#heroRecipeCount").textContent=recipes.length}
function updateFoodPreview(){const r=recipeById($("#foodSelect").value);if(!r)return;const n=autoNutrition(r),m=+$("#foodServings").value;$("#foodServingOut").textContent=m.toFixed(1)+"×";$("#foodPreview").innerHTML=[["CAL",n.calories],["CARBS",n.carbs+"G"],["PROTEIN",n.protein+"G"],["FIBER",n.fiber+"G"]].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join("")}
function activityBurn(){const mets={walk:2.8,yoga:2.5,barre:3.5,dance:5.5,pilates:3.0},mins=+$("#minutesRange").value,lb=Number(state.profile.weight)||130,kg=lb*.453592;return Math.round(mets[$("#activitySelect").value]*3.5*kg/200*mins)}function updateMovementPreview(){$("#minutesOut").textContent=+$("#minutesRange").value+" MIN";$("#burnPreview").textContent=activityBurn()+" KCAL";const facts=$("#movementFacts");if(facts)facts.innerHTML=movementFactLines().map(x=>`<span>${x}</span>`).join("")}
function updateDashboard(){const food=state.logs.filter(x=>x.type==="food"),move=state.logs.filter(x=>x.type==="move"),sums=food.reduce((a,x)=>(a.calories+=x.nutrition.calories,a.protein+=x.nutrition.protein,a.carbs+=x.nutrition.carbs,a.fat+=x.nutrition.fat,a.fiber+=x.nutrition.fiber,a),{calories:0,protein:0,carbs:0,fat:0,fiber:0}),burn=move.reduce((a,x)=>a+x.burn,0);$("#greeting").textContent=getGreeting()+(state.profile.name?`, ${state.profile.name.toUpperCase()}`:"");$("#heroXp").textContent=state.xp;$("#heroWater").textContent=state.water;$("#waterTotal").textContent=state.water;$("#waterFill").style.width=clamp(state.water/80*100,0,100)+"%";$("#calorieTotal").textContent=Math.round(sums.calories);$("#proteinTotal").textContent=Math.round(sums.protein)+"G";$("#fiberTotal").textContent=Math.round(sums.fiber)+"G";$("#burnTotal").textContent=burn;$("#gameScore").textContent=state.gameScore;if($("#gameLevel"))$("#gameLevel").textContent=state.gameLevel;if($("#gameMoves"))$("#gameMoves").textContent=state.movesLeft;if($("#gameLevelScore"))$("#gameLevelScore").textContent=state.levelScore;if($("#gameTarget"))$("#gameTarget").textContent=state.levelTarget;const maintenanceLow=2100,maintenanceHigh=2150,remainingLow=Math.max(0,maintenanceLow-Math.round(sums.calories)),remainingHigh=Math.max(0,maintenanceHigh-Math.round(sums.calories));if($("#maintenanceFill"))$("#maintenanceFill").style.width=clamp(sums.calories/maintenanceHigh*100,0,100)+"%";if($("#maintenanceText"))$("#maintenanceText").textContent=sums.calories?`${Math.round(sums.calories)} KCAL LOGGED · ${remainingLow}–${remainingHigh} KCAL TO YOUR 2,100–2,150 REFERENCE · MOVEMENT BURN ${burn} KCAL SHOWN SEPARATELY.`:"YOUR FOOD TOTAL WILL SHOW HERE · MOVEMENT BURN STAYS SEPARATE.";const macroData=[["CARBS",sums.carbs,250],["PROTEIN",sums.protein,100],["FAT",sums.fat,80],["FIBER",sums.fiber,30]];$("#macroBars").innerHTML=macroData.map(([k,v,max])=>barHtml(k,v,max,"G")).join("");const tags={"GRAINS + BASE":0,"PROTEIN":0,"FRUIT + VEG":0,"FUN + EXTRAS":0};food.forEach(x=>{const t=x.name.toLowerCase();if(/bread|bagel|pancake|oat|flour|rice|pasta|tortilla|pizza/.test(t))tags["GRAINS + BASE"]++;if(/egg|chicken|steak|yogurt|cheese|milk|cottage/.test(t))tags.PROTEIN++;if(/apple|berry|veggie|spinach|pumpkin|orange/.test(t))tags["FRUIT + VEG"]++;if(/chocolate|cookie|cake|donut|dip|sauce/.test(t))tags["FUN + EXTRAS"]++});const maxTag=Math.max(1,...Object.values(tags));$("#pyramidBars").innerHTML=Object.entries(tags).map(([k,v])=>barHtml(k,v,maxTag,"×")).join("");renderTodayLog();updateQuests();saveState()}
function barHtml(label,value,max,suffix){const pct=clamp(value/max*100,0,100);return`<div class="bar-row"><b>${label}</b><div class="bar-track"><div class="bar-fill" style="width:${pct}%"></div></div><strong>${Math.round(value)}${suffix}</strong></div>`}
function renderTodayLog(){const el=$("#todayLog");if(!state.logs.length){el.innerHTML='<div class="empty-state">YOUR FIRST LOG WILL POP UP HERE 🍓</div>';return}el.innerHTML=[...state.logs].reverse().slice(0,14).map(x=>{const time=new Date(x.at||Date.now()).toLocaleTimeString([],{hour:"numeric",minute:"2-digit"});return`<div class="log-entry"><span>${x.emoji}</span><div><b>${escapeHtml(x.name)}</b><small>${escapeHtml(x.detail)} · ${time}</small></div><strong>${x.type==="food"?x.nutrition.calories+" KCAL":x.type==="move"?x.burn+" BURN":"LOGGED"}</strong></div>`}).join("")}
function logFoodRecipe(r,mult=1){if(!r)return;const n=autoNutrition(r),scaled={calories:Math.round(n.calories*mult),protein:Math.round(n.protein*mult),carbs:Math.round(n.carbs*mult),fat:Math.round(n.fat*mult),fiber:Math.round(n.fiber*mult)};state.logs.push({type:"food",emoji:"🍽️",name:r.name,detail:`${mult.toFixed(1)}× SERVING · ${n.exact?"RECORDED / CALCULATED NUTRITION":"AUTO CCD ESTIMATE"}`,nutrition:scaled,at:Date.now()});state.xp+=25;confetti(18);toast("FOOD LOGGED +25 BERRY XP 🍓");updateDashboard()}
function logFood(){logFoodRecipe(recipeById($("#foodSelect").value),+$("#foodServings").value)}
function logMovement(){const names={walk:"GENTLE WALK",yoga:"YOGA",barre:"BARRE",dance:"JUST DANCE / MJ EXPERIENCE",pilates:"PILATES"},key=$("#activitySelect").value,mins=+$("#minutesRange").value,burn=activityBurn();state.logs.push({type:"move",emoji:"🚶🏽‍♀️",name:names[key],detail:`${mins} MIN · MET-BASED ESTIMATE`,burn,at:Date.now()});state.xp+=20;toast("MOVEMENT LOGGED +20 XP ✨");updateDashboard()}
function renderRecipes(){const q=$("#recipeSearch").value.trim().toLowerCase(),g=$("#groupFilter").value,filtered=allRecipes().filter(r=>(g==="all"||r.group===g)&&(!q||(r.name+" "+r.group+" "+(r.ingredients||[]).join(" ")).toLowerCase().includes(q)));$("#recipeCount").textContent=`SHOWING ${Math.min(filtered.length,visibleRecipes)} OF ${filtered.length} RECIPES`;$("#recipeGrid").innerHTML=filtered.slice(0,visibleRecipes).map(r=>{const n=autoNutrition(r);return`<article class="candy-card recipe-card" data-id="${escapeHtml(r.id)}"><div class="recipe-photo"><img loading="lazy" src="${recipeImage(r)}" alt="Food photography representing ${escapeHtml(r.name)}" /></div><div class="recipe-body"><span class="recipe-kicker">${escapeHtml(r.group)}</span><h3>${escapeHtml(r.name)}</h3><p>${n.exact?"RECORDED / CALCULATED NUTRITION":"AUTO CCD ESTIMATE"} · ${escapeHtml(r.yieldText||"PERSONAL CCD PORTION")}</p><div class="recipe-macros"><span class="pill">🔥 ${n.calories}</span><span class="pill">💪🏽 ${n.protein}G</span><span class="pill">🌾 ${n.fiber}G</span></div></div></article>`}).join("");$$('.recipe-card img').forEach(i=>safeImg(i,"🍓"));$$('.recipe-card').forEach(c=>c.addEventListener('click',()=>openRecipe(c.dataset.id)));$("#loadMore").hidden=visibleRecipes>=filtered.length}
function openRecipe(id){const r=recipeById(id);if(!r)return;const n=autoNutrition(r),ingredients=r.ingredients?.length?r.ingredients:["EXACT ORIGINAL INGREDIENT AMOUNTS WERE NOT RECOVERED FOR THIS ARCHIVE ENTRY."],steps=r.steps?.length?r.steps:["OPEN THIS AS A CCD ARCHIVE IDEA AND BUILD IT FROM A VERIFIED RECIPE FORMULA BEFORE COOKING."];$("#recipeDialogBody").innerHTML=`<div class="recipe-hero"><img src="${recipeImage(r)}" alt="Food photography representing ${escapeHtml(r.name)}"><div class="recipe-hero-copy"><span class="eyebrow">${escapeHtml(r.group)}</span><h2>${escapeHtml(r.name)}</h2><p>${escapeHtml(r.source||"CCD ARCHIVE")}</p></div></div><div class="recipe-detail-body"><div class="dialog-macro-grid">${[["CALORIES",n.calories],["CARBS",n.carbs+"G"],["PROTEIN",n.protein+"G"],["FAT",n.fat+"G"],["FIBER",n.fiber+"G"]].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join("")}</div><small>${n.exact?"RECORDED OR INGREDIENT-CALCULATED NUTRITION":"AUTO CCD ESTIMATE FOR ENTRIES WITHOUT COMPLETE RECORDED MACROS"}</small><div class="serving-calc"><div class="range-row"><label for="dialogServing">TOTAL CALORIE SLIDER</label><output id="dialogServingOut">1.0× SERVING</output></div><input id="dialogServing" class="berry-range" type="range" min="0.5" max="4" step="0.5" value="1"><div class="serving-total"><span>PER SERVING: ${n.calories} KCAL</span><strong id="dialogTotalCalories">${n.calories} KCAL TOTAL</strong></div></div><div class="taste-box"><h3>WHAT TO EXPECT / WHAT IT TASTES LIKE 😋</h3><p>${escapeHtml(tasteText(r))}</p></div><h3>THREE CCD ONE-LINERS ✨</h3><div class="recipe-fact-grid">${recipeFacts(r).map(x=>`<div>${escapeHtml(x)}</div>`).join("")}</div><h3>INGREDIENT CHART 🥣</h3><div class="ingredient-chart">${ingredients.map((x,i)=>`<div class="ingredient-row"><span>${String(i+1).padStart(2,"0")}</span><b>${escapeHtml(x)}</b></div>`).join("")}</div><h3>METHOD ✨</h3><ol class="method-list">${steps.map((x,i)=>`<li><b>${i+1}.</b> ${escapeHtml(x)}</li>`).join("")}</ol><button class="primary-button full" id="dialogLogFood">LOG THIS RECIPE 🍽️</button></div>`;const d=$("#recipeDialog");d.showModal();safeImg($('.recipe-hero img'),"🍰");$("#dialogServing").addEventListener("input",e=>{$("#dialogServingOut").textContent=(+e.target.value).toFixed(1)+"× SERVING";$("#dialogTotalCalories").textContent=Math.round(n.calories*+e.target.value)+" KCAL TOTAL"});$("#dialogLogFood").addEventListener("click",()=>{logFoodRecipe(r,+$("#dialogServing").value);d.close()})}
function battleStats(){const a=recipeById($("#battleA").value),b=recipeById($("#battleB").value);[["#fighterAStats",a],["#fighterBStats",b]].forEach(([sel,r])=>{if(!r)return;const n=autoNutrition(r);$(sel).innerHTML=[["CAL",n.calories],["PROTEIN",n.protein+"G"],["FIBER",n.fiber+"G"],["CARBS",n.carbs+"G"]].map(x=>`<div><strong>${x[1]}</strong><span>${x[0]}</span></div>`).join("")})}
