function initBoard(){gameLocked=false;board=Array.from({length:36},()=>GAME_PIECES[Math.floor(Math.random()*GAME_PIECES.length)]);selectedGem=null;while(findMatches().size)board=Array.from({length:36},()=>GAME_PIECES[Math.floor(Math.random()*GAME_PIECES.length)]);renderBoard()}
function renderBoard(burst=new Set()){const el=$("#matchBoard");el.innerHTML=board.map((p,i)=>`<button class="gem ${selectedGem===i?"selected":""} ${burst.has(i)?"burst":""}" data-i="${i}" role="gridcell" aria-label="${p} Berry Burst game piece">${p}</button>`).join("");$$('.gem',el).forEach(x=>x.addEventListener('click',()=>gemClick(+x.dataset.i)))}
function adjacent(a,b){const ar=Math.floor(a/6),ac=a%6,br=Math.floor(b/6),bc=b%6;return Math.abs(ar-br)+Math.abs(ac-bc)===1}
function gemClick(i){if(gameLocked)return;if(state.movesLeft<=0){toast("NO MOVES LEFT — TAP NEW LEVEL 🍓");return}if(selectedGem===null){selectedGem=i;renderBoard();return}if(i===selectedGem){selectedGem=null;renderBoard();return}if(!adjacent(selectedGem,i)){selectedGem=i;renderBoard();return}const a=selectedGem;[board[a],board[i]]=[board[i],board[a]];selectedGem=null;const matches=findMatches();if(!matches.size){[board[a],board[i]]=[board[i],board[a]];$("#comboMessage").textContent="NO MATCH — TRY ANOTHER SWAP 😜";renderBoard();return}state.movesLeft=Math.max(0,state.movesLeft-1);gameLocked=true;saveState();updateDashboard();resolveMatches(matches)}
function findMatches(){const s=new Set();for(let r=0;r<6;r++)for(let c=0;c<4;c++){const i=r*6+c;if(board[i]&&board[i]===board[i+1]&&board[i]===board[i+2]){s.add(i);s.add(i+1);s.add(i+2)}}for(let c=0;c<6;c++)for(let r=0;r<4;r++){const i=r*6+c;if(board[i]&&board[i]===board[i+6]&&board[i]===board[i+12]){s.add(i);s.add(i+6);s.add(i+12)}}return s}
function resolveMatches(matches,chain=1){renderBoard(matches);const gained=matches.size*25*chain;state.gameScore+=gained;state.levelScore+=gained;state.xp+=Math.round(gained/10);$("#comboMessage").textContent=`BERRY BURST! +${gained} SCORE ${chain>1?`· ${chain}× CHAIN 🔥`:"💥"}`;saveState();updateDashboard();setTimeout(()=>{for(const i of matches)board[i]=null;collapseBoard();const next=findMatches();renderBoard();if(next.size)setTimeout(()=>resolveMatches(next,chain+1),240);else finishGameTurn()},300)}
function collapseBoard(){for(let c=0;c<6;c++){let vals=[];for(let r=5;r>=0;r--){const v=board[r*6+c];if(v)vals.push(v)}for(let r=5,k=0;r>=0;r--,k++)board[r*6+c]=vals[k]||GAME_PIECES[Math.floor(Math.random()*GAME_PIECES.length)]}}
function finishGameTurn(){if(state.levelScore>=state.levelTarget){const boardEl=$("#matchBoard");boardEl.classList.add("level-complete");$("#comboMessage").textContent=`LEVEL ${state.gameLevel} CRUSHED! 🏆 +100 XP`;state.xp+=100;confetti(42);saveState();updateDashboard();setTimeout(()=>{boardEl.classList.remove("level-complete");startNewLevel(true)},850);return}if(state.movesLeft<=0){$("#comboMessage").textContent=`OUT OF MOVES · ${state.levelScore}/${state.levelTarget} — TAP NEW LEVEL 🍓`;toast("LEVEL OVER — TRY A FRESH BOARD 🎮")}gameLocked=false;saveState();updateDashboard()}
function startNewLevel(advance=false){gameLocked=false;if(advance)state.gameLevel+=1;state.levelScore=0;state.movesLeft=25;state.levelTarget=1000+(state.gameLevel-1)*250;selectedGem=null;saveState();initBoard();updateDashboard();$("#comboMessage").textContent=advance?`LEVEL ${state.gameLevel}! TARGET ${state.levelTarget} 🎯`:`FRESH LEVEL ${state.gameLevel} · TARGET ${state.levelTarget} 🍓`;if(!advance)toast("FRESH BERRY BURST LEVEL 🎮")}
function updateQuests(){[[300,"#quest300"],[750,"#quest750"],[1500,"#quest1500"]].forEach(([n,s])=>$(s).textContent=state.gameScore>=n?"✓":"○")}function confetti(n=24){const layer=$("#confettiLayer"),pieces=["🍓","🫐","✨","⭐","💜"];for(let i=0;i<n;i++){const e=document.createElement("span");e.className="confetti";e.textContent=pieces[i%pieces.length];e.style.left=Math.random()*100+"vw";e.style.animationDelay=Math.random()*.35+"s";e.style.fontSize=14+Math.random()*18+"px";layer.appendChild(e);setTimeout(()=>e.remove(),2200)}}
function fastPreset(){return FAST_PRESETS.find(x=>x.id===(state.fastMode||"16:8"))||FAST_PRESETS[2]}
function syncFastType(){const select=$("#fastType");if(!select)return;if(!FAST_PRESETS.some(x=>x.id===state.fastMode))state.fastMode="16:8";select.value=state.fastMode;const preset=fastPreset();$("#fastTargetLabel").textContent=`TARGET · ${preset.hours} HOURS`;if(!state.fastStart){$("#fastTargetPct").textContent="0%";$("#fastProgressFill").style.width="0%"}}
function startFast(){if(state.fastStart){toast("FASTING TIMER IS ALREADY RUNNING ⏳");return}state.fastMode=$("#fastType")?.value||state.fastMode||"16:8";state.fastStart=Date.now();saveState();startFastTicker();toast(`${state.fastMode} FAST STARTED ✨`)}
function stopFast(){if(!state.fastStart){toast("START THE TIMER FIRST 🍓");return}const ms=Date.now()-state.fastStart,preset=fastPreset(),hit=ms>=preset.hours*3600000;state.fastHistory.push({duration:ms,mode:state.fastMode,targetHours:preset.hours,hitTarget:hit,endedAt:Date.now()});state.logs.push({type:"fast",emoji:"⏳",name:`FAST · ${state.fastMode}`,detail:`${formatDuration(ms)} · ${hit?"TARGET REACHED 🏆":`TARGET ${preset.hours}H`}`,at:Date.now()});state.fastStart=null;state.xp+=hit?20:10;saveState();startFastTicker();toast(hit?"FAST TARGET REACHED +20 XP 🏆":"FAST SAVED +10 XP ⏳");updateDashboard()}
function formatDuration(ms){const sec=Math.floor(ms/1000),h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return`${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`}
function startFastTicker(){clearInterval(fastTicker);syncFastType();const paint=()=>{const preset=fastPreset(),targetMs=preset.hours*3600000;if(state.fastStart){const elapsed=Date.now()-state.fastStart,pct=Math.min(100,elapsed/targetMs*100);$("#fastClock").textContent=formatDuration(elapsed);$("#fastStatus").textContent=elapsed>=targetMs?`${state.fastMode} TARGET REACHED 🏆`:`${state.fastMode} FASTING IN PROGRESS ✨`;$("#fastTargetLabel").textContent=`TARGET · ${preset.hours} HOURS`;$("#fastTargetPct").textContent=Math.floor(pct)+"%";$("#fastProgressFill").style.width=pct+"%"}else{$("#fastClock").textContent="00:00:00";$("#fastStatus").textContent=`READY FOR ${state.fastMode||"16:8"} ✨`;$("#fastTargetLabel").textContent=`TARGET · ${preset.hours} HOURS`;$("#fastTargetPct").textContent="0%";$("#fastProgressFill").style.width="0%"}};paint();if(state.fastStart)fastTicker=setInterval(paint,1000)}
function openProfile(){const p=state.profile;$("#profileName").value=p.name||"";$("#profileHeight").value=p.height||"";$("#profileWeight").value=p.weight||"";$("#profileReason").value=p.reason||"";$("#themeSelect").value=$("#themeSelect").querySelector(`option[value="${p.theme||"berry"}"]`)?(p.theme||"berry"):"berry";$("#accentColor").value=p.accent||"#7f3cff";setProfilePreview(p.photo);$("#profileDialog").showModal()}function setProfilePreview(src){const img=$("#profilePreview");if(src){img.src=src;img.alt="Uploaded profile picture"}else{img.removeAttribute("src");img.alt="Profile image placeholder";img.style.background="linear-gradient(145deg,var(--lav),#fff)"}}function saveProfile(e){e.preventDefault();state.profile={...state.profile,name:$("#profileName").value.trim(),height:$("#profileHeight").value.trim(),weight:$("#profileWeight").value,reason:$("#profileReason").value.trim(),theme:$("#themeSelect").value,accent:$("#accentColor").value};saveState();applyTheme();updateMovementPreview();updateDashboard();$("#profileDialog").close();toast("PROFILE SAVED 💜")}
function readProfilePic(file){if(!file)return;const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas"),ctx=canvas.getContext("2d"),size=320;canvas.width=size;canvas.height=size;const scale=Math.max(size/img.width,size/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(size-w)/2,(size-h)/2,w,h);state.profile.photo=canvas.toDataURL("image/jpeg",.8);saveState();setProfilePreview(state.profile.photo)};img.src=reader.result};reader.readAsDataURL(file)}function escapeHtml(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}

const AUTH_USERS_KEY="berryVibesLocalUsersV1",AUTH_SESSION_KEY="berryVibesLocalSessionV1";
function getAuthUsers(){try{return JSON.parse(localStorage.getItem(AUTH_USERS_KEY)||"[]")}catch{return[]}}
function setAuthUsers(users){localStorage.setItem(AUTH_USERS_KEY,JSON.stringify(users))}
function bytesToHex(buf){return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,"0")).join("")}
async function hashPassword(password,salt){const data=new TextEncoder().encode(salt+"::"+password),digest=await crypto.subtle.digest("SHA-256",data);return bytesToHex(digest)}
function setAuthMode(mode){const signIn=mode==="signin";$("#authSignInTab").classList.toggle("active",signIn);$("#authSignUpTab").classList.toggle("active",!signIn);$("#signInForm").hidden=!signIn;$("#signInForm").classList.toggle("hidden",!signIn);$("#signUpForm").hidden=signIn;$("#signUpForm").classList.toggle("hidden",signIn)}
function authSession(){try{return JSON.parse(localStorage.getItem(AUTH_SESSION_KEY)||"null")}catch{return null}}
function revealSite(session){$("#authGate").classList.add("hidden");$("#authUserChip").textContent=(session?.name||state.profile.name||"BERRY PROFILE").toUpperCase()}
function requireAuth(){const s=authSession();if(s?.email)revealSite(s);else $("#authGate").classList.remove("hidden")}
async function handleSignUp(e){e.preventDefault();const name=$("#signUpName").value.trim(),email=$("#signUpEmail").value.trim().toLowerCase(),password=$("#signUpPassword").value;if(getAuthUsers().some(u=>u.email===email)){toast("THAT LOCAL EMAIL ALREADY EXISTS 🍓");return}const salt=crypto.getRandomValues(new Uint32Array(4)).join("-");const passwordHash=await hashPassword(password,salt),users=getAuthUsers();users.push({name,email,salt,passwordHash,createdAt:Date.now()});setAuthUsers(users);localStorage.setItem(AUTH_SESSION_KEY,JSON.stringify({name,email}));if(!state.profile.name)state.profile.name=name;saveState();revealSite({name,email});updateDashboard();toast("LOCAL BERRY PROFILE CREATED ✨")}
async function handleSignIn(e){e.preventDefault();const email=$("#signInEmail").value.trim().toLowerCase(),password=$("#signInPassword").value,user=getAuthUsers().find(u=>u.email===email);if(!user||await hashPassword(password,user.salt)!==user.passwordHash){toast("EMAIL OR PASSWORD DOESN’T MATCH THIS DEVICE 🍓");return}localStorage.setItem(AUTH_SESSION_KEY,JSON.stringify({name:user.name,email:user.email}));if(!state.profile.name)state.profile.name=user.name;saveState();revealSite(user);updateDashboard();toast("WELCOME BACK 🍓✨")}
